def test_cosh_acos_acosh_is_zero_recursion():
    import pytest
    from sympy import cosh, acos, acosh, I, Symbol
    g = Symbol('g')
    expr = cosh(acos(-I + acosh(-g + I)))
    try:
        result = expr.is_zero
    except RecursionError as e:
        pytest.fail(f"RecursionError occurred: {e}")
    assert result in (True, False, None)
